/// Computes the arithmetic series sum S(n) = 1 + 2 + ... + n.
/// Assumes that S(n) < 10_000, so no overflow on u64.
pub fn compute_arith_sum(n: u64) -> u64 {
    let mut sum = 0;
    let mut i = 1;
    while i <= n {
        sum += i;
        i += 1;
    }
    sum
}

